import os
from typing import Any, Dict, List

from google.cloud import vision


def detect_text_in_image(image_path: str) -> List[Dict[str, Any]]:
    """
    Detect text appearing inside an image using Google Cloud Vision.

    Returns a list of dictionaries containing detected text and bounding box vertices.
    """
    client = vision.ImageAnnotatorClient()

    with open(image_path, "rb") as f:
        content = f.read()

    image = vision.Image(content=content)
    response = client.text_detection(image=image)

    if response.error.message:
        raise RuntimeError(response.error.message)

    results: List[Dict[str, Any]] = []
    for annotation in response.text_annotations:
        vertices = []
        if annotation.bounding_poly and annotation.bounding_poly.vertices:
            for v in annotation.bounding_poly.vertices:
                vertices.append({"x": v.x, "y": v.y})

        results.append(
            {
                "text": annotation.description,
                "bounding_box": vertices,
            }
        )

    return results


def detect_text(image_path: str) -> List[Dict[str, Any]]:
    return detect_text_in_image(image_path)


if __name__ == "__main__":
    import sys
    import json

    if len(sys.argv) != 2:
        raise SystemExit("Usage: python script.py /path/to/image")

    output = detect_text_in_image(sys.argv[1])
    print(json.dumps(output, ensure_ascii=False, indent=2))
